import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

fused_gn_mean_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <math.h>

#define CEIL_DIV(a, b) ((a) + (b) - 1) / (b)

constexpr int THREADS = 256;
constexpr float EPS = 1e-5;

__device__ void warp_reduce(volatile float* sdata, int tid) {
    sdata[tid] += sdata[tid + 32];
    sdata[tid] += sdata[tid + 16];
    sdata[tid] += sdata[tid + 8];
    sdata[tid] += sdata[tid + 4];
    sdata[tid] += sdata[tid + 2];
    sdata[tid] += sdata[tid + 1];
}

__global__ void fused_gn_mean_kernel(
    const float* __restrict__ input,
    const float* __restrict__ gamma,
    const float* __restrict__ beta,
    float* __restrict__ output,
    int B, int C, int D, int H, int W,
    int G, int elements_per_batch
) {
    extern __shared__ float smem[];
    float* s_sum = smem;
    float* s_sqsum = smem + blockDim.x;

    int bid = blockIdx.x;
    int c_grp = blockIdx.y;
    int tid = threadIdx.x;

    int channels_per_grp = C / G;
    int elements_per_grp = channels_per_grp * D * H * W;

    float sum = 0.0f, sqsum = 0.0f;

    for(int i = tid; i < elements_per_grp; i += blockDim.x) {
        int c = c_grp * channels_per_grp + i / (D*H*W);
        int spatial_idx = i % (D*H*W);
        int idx = ((bid * C + c) * D * H + spatial_idx / W) * W + spatial_idx % W;
        float val = input[idx];
        sum += val;
        sqsum += val * val;
    }

    s_sum[tid] = sum;
    s_sqsum[tid] = sqsum;
    __syncthreads();

    for(int s = blockDim.x/2; s > 32; s >>= 1) {
        if(tid < s) {
            s_sum[tid] += s_sum[tid + s];
            s_sqsum[tid] += s_sqsum[tid + s];
        }
        __syncthreads();
    }
    if(tid < 32) {
        warp_reduce(s_sum, tid);
        warp_reduce(s_sqsum, tid);
    }

    if(tid == 0) {
        float mean = s_sum[0] / elements_per_grp;
        float var = (s_sqsum[0] / elements_per_grp) - mean * mean;
        smem[0] = mean;
        smem[1] = var;
    }
    __syncthreads();

    float mean = smem[0];
    float inv_std = rsqrtf(smem[1] + EPS);
    float batch_sum = 0.0f;

    for(int i = tid; i < elements_per_grp; i += blockDim.x) {
        int c = c_grp * channels_per_grp + i / (D*H*W);
        int spatial_idx = i % (D*H*W);
        int idx = ((bid * C + c) * D * H + spatial_idx / W) * W + spatial_idx % W;
        float val = (input[idx] - mean) * inv_std;
        val = val * gamma[c] + beta[c];
        batch_sum += val;
    }

    s_sum[tid] = batch_sum;
    __syncthreads();

    for(int s = blockDim.x/2; s > 32; s >>= 1) {
        if(tid < s) s_sum[tid] += s_sum[tid + s];
        __syncthreads();
    }
    if(tid < 32) warp_reduce(s_sum, tid);

    if(tid == 0) {
        atomicAdd(&output[bid], s_sum[0] / elements_per_batch);
    }
}

torch::Tensor fused_gn_mean_cuda(
    torch::Tensor input,
    torch::Tensor gamma,
    torch::Tensor beta,
    int num_groups
) {
    int B = input.size(0);
    int C = input.size(1);
    int D = input.size(2);
    int H = input.size(3);
    int W = input.size(4);
    int G = num_groups;
    int elements_per_batch = C * D * H * W;

    auto output = torch::zeros({B}, input.options());

    dim3 blocks(B, G);
    int shmem_size = 2 * THREADS * sizeof(float);

    fused_gn_mean_kernel<<<blocks, THREADS, shmem_size>>>(
        input.data_ptr<float>(),
        gamma.data_ptr<float>(),
        beta.data_ptr<float>(),
        output.data_ptr<float>(),
        B, C, D, H, W,
        G, elements_per_batch
    );

    return output;
}
"""

fused_gn_mean_cpp = "torch::Tensor fused_gn_mean_cuda(torch::Tensor input, torch::Tensor gamma, torch::Tensor beta, int num_groups);"

fused_gn_mean = load_inline(
    name='fused_gn_mean',
    cpp_sources=fused_gn_mean_cpp,
    cuda_sources=fused_gn_mean_source,
    functions=['fused_gn_mean_cuda'],
    verbose=True
)

class ModelNew(nn.Module):
    def __init__(self, in_channels, out_channels, kernel_size, num_groups):
        super(ModelNew, self).__init__()
        self.conv = nn.Conv3d(in_channels, out_channels, kernel_size)
        self.num_groups = num_groups
        self.gamma = nn.Parameter(torch.ones(out_channels))
        self.beta = nn.Parameter(torch.zeros(out_channels))

    def forward(self, x):
        x = self.conv(x)
        x = fused_gn_mean.fused_gn_mean_cuda(x, self.gamma, self.beta, self.num_groups)
        return x.unsqueeze(1)
